const PASOS = [ { nom:'Solicitante' }, { nom:'Puesto' }, { nom:'Condiciones' }, { nom:'Motivo' }, { nom:'Activos' } ];

/* Índices de apoyo */
const CAMPO = {};
CARDS.forEach(card => card.campos.forEach((c, i) => {
  c.k = c.id || c.k || (card.id + '_' + i); c.card = card.id; c.paso = card.paso; CAMPO[c.k] = c;
}));
function todos(){ const r = []; CARDS.forEach(card => card.campos.forEach(c => r.push(c))); return r; }
function cardVisible(card, d){ return !card.cond || !!card.cond(d || {}); }
function visible(c, d){ d = d || {}; const card = CARDS.find(x => x.id === c.card);
  return (!card || cardVisible(card, d)) && (!c.cond || !!c.cond(d)); }
function etiqueta(c, d){ return typeof c.l === 'function' ? c.l(d || {}) : c.l; }
function etiquetaPDF(c, d){ return c.pl || etiqueta(c, d); }

/* ================== BORRADOR (en el equipo del solicitante) ================== */
const LS_KEY = 'mdk_requisicion';
function cargarBorrador(){ try{ return JSON.parse(localStorage.getItem(LS_KEY) || 'null'); }catch(e){ return null; } }
function guardarBorrador(b){ try{ localStorage.setItem(LS_KEY, JSON.stringify(b)); }catch(e){} }
function borrarBorrador(){ try{ localStorage.removeItem(LS_KEY); }catch(e){} }
function nuevoBorrador(){
  return { id:'req_' + Date.now() + '_' + Math.random().toString(36).slice(2,8),
           folio:'', d:{}, paso:0, acepto:false, creado:new Date().toISOString() };
}
function tieneDatos(b){ return !!(b && b.d && Object.keys(b.d).some(k => CAMPO[k] && !vacio(b.d[k]))); }

/* ================== UTILIDADES ================== */
function online(){ return navigator.onLine !== false; }
function esc(s){ return String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function hoyISO(){ const d = new Date(); d.setMinutes(d.getMinutes() - d.getTimezoneOffset()); return d.toISOString().slice(0,10); }
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
function fechaFormato(f){
  const m = String(f || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? m[3] + ' / ' + MESES[Number(m[2]) - 1] + ' / ' + m[1] : '';
}
function num(v){ const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.\-]/g,'')); return isNaN(n) ? null : n; }
function fmtMoney(v){ const n = num(v); return n == null ? '' : '$' + n.toLocaleString('es-MX', { maximumFractionDigits:2 }); }
function fechaCorta(f){ const m = String(f || '').match(/^(\d{4})-(\d{2})-(\d{2})$/); return m ? m[3] + '/' + m[2] + '/' + m[1] : String(f || ''); }
function fmtSize(b){ return b > 1048576 ? (b / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(b / 1024)) + ' KB'; }
function vacio(v){ return v == null || (Array.isArray(v) ? !v.some(x => x && String(x).trim()) : String(v).trim() === ''); }

function valorTexto(c, d){
  if(c.val) return c.val(d);
  const v = d[c.id];
  if(c.t === 'money') return fmtMoney(v);
  if(c.t === 'tel') return String(v || '').replace(/\D/g,'');
  if(c.t === 'lista') return (Array.isArray(v) ? v : []).filter(x => x && String(x).trim()).join('\n');
  if(c.t === 'checks') return (Array.isArray(v) ? v : []).join(', ');
  if(c.t === 'date') return fechaCorta(v);
  return v == null ? '' : String(v).trim();
}
function valorPlano(c, d){
  if(c.val) return c.val(d);
  const v = d[c.id];
  if(c.t === 'money' || c.t === 'number'){ const n = num(v); return n == null ? '' : n; }
  if(c.t === 'tel') return String(v || '').replace(/\D/g,'');
  if(c.t === 'lista') return (Array.isArray(v) ? v : []).filter(x => x && String(x).trim()).map(x => '• ' + String(x).trim()).join('\n');
  if(c.t === 'checks') return (Array.isArray(v) ? v : []).join(', ');
  if(c.t === 'date') return fechaCorta(v);
  return v == null ? '' : String(v).trim();
}
function columnasSheet(b){
  const cols = [['Folio', b.folio || ''], ['Fecha de solicitud', fechaCorta(b.fecha || hoyISO())]];
  todos().forEach(c => {
    if(!c.id || c.nocol) return;
    cols.push([c.col || etiquetaPDF(c, b.d), visible(c, b.d) ? valorPlano(c, b.d) : '']);
  });
  return cols;
}

/* ================== VALIDACION ================== */
function errorCampo(c, d){
  if(!c.id || !visible(c, d)) return '';
  const v = d[c.id];
  if(vacio(v)) return c.req ? 'Este dato es obligatorio.' : '';
  if(c.t === 'lista' && c.req === 'todos'){
    const arr = Array.isArray(v) ? v : [];
    for(let i = 0; i < (c.n || 3); i++) if(!arr[i] || !String(arr[i]).trim()) return 'Escribe las ' + (c.n || 3) + '. Te falta la número ' + (i + 1) + '.';
  }
  if(c.t === 'tel' && String(v).replace(/\D/g,'').length !== 10) return 'Escribe 10 dígitos, sin espacios. Ej. 5512345678';
  if(c.t === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(v).trim())) return 'Revisa el correo. Ej. nombre@correo.com';
  if(c.t === 'number'){
    if(!/^\s*\d+\s*$/.test(String(v))) return 'Escribe solo números enteros.';
    const n = num(v);
    if((c.min != null && n < c.min) || (c.max != null && n > c.max)) return 'Revisa este número.';
  }
  if(c.t === 'money' && num(v) == null) return 'Escribe solo la cantidad, sin letras. Ej. 12000';
  if(c.t === 'date'){
    if(!/^\d{4}-\d{2}-\d{2}$/.test(String(v))) return 'Elige una fecha válida.';
    if(c.minHoy && v < hoyISO()) return 'La fecha no puede ser anterior a hoy.';
    if(c.despuesDe && d[c.despuesDe] && v < d[c.despuesDe]) return 'Debe ser igual o posterior a la fecha de inicio.';
  }
  return '';
}
function erroresPaso(p, d){
  const r = [];
  CARDS.filter(card => card.paso === p).forEach(card => card.campos.forEach(c => {
    const m = errorCampo(c, d); if(m) r.push({ c, m });
  }));
  return r;
}

/* ================== PANTALLA: campos ================== */
function htmlCampo(c, d){
  const full = (c.w === 'full' || c.t === 'nota') ? ' full' : '';
  const attrs = ' data-k="' + c.k + '"' + (visible(c, d) ? '' : ' hidden');
  if(c.t === 'nota') return '<div class="nota' + full + '"' + attrs + '>' + c.l + '</div>';

  const v = d[c.id];
  const req = c.req ? ' <b class="req">*</b>' : '';
  const ayuda = c.ej ? '<p class="ayuda">' + esc(c.ej) + '</p>' : '';
  const ph = c.ph ? ' placeholder="' + esc(c.ph) + '"' : '';
  const err = '<p class="ferr"></p>';
  const abre = '<div class="field' + full + '"' + attrs + '>';
  const labFor = '<label class="q" for="f_' + c.id + '">' + esc(etiqueta(c, d)) + req + '</label>';
  const labSin = '<label class="q">' + esc(etiqueta(c, d)) + req + '</label>';
  switch(c.t){
    case 'select':
      return abre + labFor + ayuda + '<select id="f_' + c.id + '" data-f="' + c.id + '"><option value="">Selecciona una opción…</option>' +
        c.op.map(o => '<option' + (v === o ? ' selected' : '') + '>' + esc(o) + '</option>').join('') + '</select>' + err + '</div>';
    case 'seg':
      return abre + labSin + ayuda + '<div class="seg' + (c.multi ? ' multi' : '') + '" role="radiogroup">' +
        c.op.map(o => '<button type="button" role="radio" aria-checked="' + (v === o) + '" data-f="' + c.id + '" data-v="' + esc(o) + '" class="' + (v === o ? 'sel' : '') + '">' + esc(o) + '</button>').join('') +
        '</div>' + err + '</div>';
    case 'checks': {
      const arr = Array.isArray(v) ? v : [];
      return abre + labSin + ayuda + '<div class="seg multi checks" role="group">' +
        c.op.map(o => { const s = arr.indexOf(o) >= 0; return '<button type="button" role="checkbox" aria-checked="' + s + '" data-f="' + c.id + '" data-v="' + esc(o) + '" data-multi="1" class="' + (s ? 'sel' : '') + '"><span class="ck" aria-hidden="true"></span>' + esc(o) + '</button>'; }).join('') +
        '</div>' + err + '</div>';
    }
    case 'date':
      return abre + labFor + ayuda + '<input id="f_' + c.id + '" type="date" data-f="' + c.id + '" value="' + esc(v || '') + '"' + (c.minHoy ? ' min="' + hoyISO() + '"' : '') + '>' + err + '</div>';
    case 'area':
      return abre + labFor + ayuda + '<textarea id="f_' + c.id + '" data-f="' + c.id + '" maxlength="1500"' + ph + '>' + esc(v || '') + '</textarea>' + err + '</div>';
    case 'lista': {
      const arr = Array.isArray(v) ? v : [];
      let li = '';
      for(let i = 0; i < (c.n || 3); i++)
        li += '<div class="li"><span class="dot">' + (i + 1) + '</span><input data-f="' + c.id + '" data-i="' + i + '" maxlength="300" value="' +
          esc(arr[i] || '') + '" placeholder="' + esc((c.phs || [])[i] || '') + '"></div>';
      return abre + labSin + ayuda + '<div class="lista">' + li + '</div>' + err + '</div>';
    }
    case 'money':
      return abre + labFor + ayuda + '<div class="money"><span>$</span><input id="f_' + c.id + '" data-f="' + c.id + '" inputmode="decimal" maxlength="12" value="' + esc(v || '') + '"' + ph + '></div>' + err + '</div>';
    default: {
      const type = { email:'email', tel:'tel' }[c.t] || 'text';
      const extra = c.t === 'number' ? ' inputmode="numeric" maxlength="2"' : (c.t === 'tel' ? ' inputmode="tel" maxlength="14" autocomplete="tel"' : ' maxlength="150"');
      const ac = c.id === 'solNombre' ? ' autocomplete="name"' : (c.t === 'email' ? ' autocomplete="email"' : (c.t === 'tel' ? '' : ' autocomplete="off"'));
      const dl = c.list ? ' list="dl_' + c.id + '"' : '';
      return abre + labFor + ayuda + '<input id="f_' + c.id + '" type="' + type + '" data-f="' + c.id + '" value="' + esc(v || '') + '"' + ph + extra + ac + dl + '>' +
        (c.list ? '<datalist id="dl_' + c.id + '">' + c.list.map(o => '<option value="' + esc(o) + '">').join('') + '</datalist>' : '') + err + '</div>';
    }
  }
}
function htmlCard(card, d){
  return '<section class="card" data-card="' + card.id + '"' + (cardVisible(card, d) ? '' : ' hidden') + '>' +
    '<h2><span class="num ic">' + card.ic + '</span>' + esc(card.tit) + '</h2>' +
    (card.hint ? '<p class="hint">' + esc(card.hint) + '</p>' : '') +
    '<div class="grid">' + card.campos.map(c => htmlCampo(c, d)).join('') + '</div></section>';
}


/* ================== CONEXION ================== */
async function pedirFolio(){
  const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 20000);
  const r = await fetch(SURL + '?accion=folio', { signal:ctrl.signal }); clearTimeout(t);
  const d = await r.json();
  if(!d || typeof d.consec !== 'number') throw new Error(d && d.msg ? d.msg : 'No se pudo obtener el folio');
  return PREFIJO + '-' + String(d.consec).padStart(3, '0');
}
async function postServidor(o){
  const body = JSON.stringify(o);
  try{
    const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 120000);
    const r = await fetch(SURL, { method:'POST', redirect:'follow',
      headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body, signal:ctrl.signal });
    clearTimeout(t);
    const txt = await r.text();
    let d = null; try{ d = JSON.parse(txt); }catch(e){}
    if(d && d.status === 'ok') return d;
    if(d && d.status === 'error') throw new Error(d.msg);
    throw new Error('Respuesta inesperada del servidor');
  }catch(err){
    /* Si el navegador no deja leer la respuesta (CORS) se reenvía "a ciegas".
       El servidor reconoce la solicitud por su ID, así que no se duplica. */
    if(err && err.name === 'TypeError' && online()){
      await fetch(SURL, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body });
      return { status:'ok', ciego:true };
    }
    throw err;
  }
}


function bytesToBase64(u8){
  let s = ''; const CH = 0x8000;
  for(let i = 0; i < u8.length; i += CH) s += String.fromCharCode.apply(null, u8.subarray(i, i + CH));
  return btoa(s);
}
function slugNombre(n){
  return String(n || 'Candidato').normalize('NFD').replace(/[̀-ͯ]/g,'')
    .replace(/[^A-Za-z0-9 ]+/g,'').trim().replace(/\s+/g,' ').slice(0,60) || 'Candidato';
}

/* ================== PDF (hoja carta, igual al formato en Word) ================== */
const PW = 215.9, PH = 279.4, MX = 15, ANCHO = PW - 2 * MX, PIE_Y = PH - 22, LIMITE = PIE_Y - 5, TOPE_PAG = 36;
const AZUL = [26,16,128], GRIS = [106,102,136], TINTA = [27,24,48], LINEA = [196,193,214], SUAVE = [239,234,251];

/* La fuente estándar del PDF solo pinta Latin-1: se normaliza lo demás */
function pdfTxt(s){
  return String(s == null ? '' : s).normalize('NFC')
    .replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-').replace(/…/g, '...').replace(/•/g, '-')
    .replace(/[^\x09\x0A\x0D\x20-\x7E\xA0-\xFF]/g, '');
}
function fuente(doc, estilo, tam, color){ doc.setFont('helvetica', estilo); doc.setFontSize(tam); if(color) doc.setTextColor(...color); }
/* Parte el texto en renglones que caben en "ancho" (también palabras larguísimas sin espacios) */
function renglones(doc, txt, ancho){
  const out = [];
  String(txt).split('\n').forEach(par => {
    if(!par.trim()){ if(out.length) out.push(''); return; }
    const partes = par.split(' ').map(w => {
      if(doc.getTextWidth(w) <= ancho) return w;
      let r = '', cur = '';
      for(const ch of w){ if(doc.getTextWidth(cur + ch) > ancho){ r += cur + ' '; cur = ch; } else cur += ch; }
      return r + cur;
    });
    doc.splitTextToSize(partes.join(' '), ancho).forEach(l => out.push(l));
  });
  while(out.length && out[out.length - 1] === '') out.pop();
  return out;
}

/* Hoja membretada: logo arriba a la izquierda, marca de agua al centro y pie con dirección y teléfonos */
function pdfMembrete(doc, b, primera){
  const mw = 150, mh = mw / LOGO_RATIO;
  try{ doc.addImage(MARCA_AGUA, 'PNG', (PW - mw) / 2, (PH - mh) / 2 - 4, mw, mh, 'marca', 'FAST'); }catch(x){}
  const lw = 52.3, lh = lw / LOGO_RATIO;
  let ok = false;
  if(LOGO && LOGO.indexOf('data:') === 0){ try{ doc.addImage(LOGO, 'PNG', 9, 7, lw, lh, 'logo', 'FAST'); ok = true; }catch(x){} }
  if(!ok){ fuente(doc, 'bold', 16, AZUL); doc.text('MDreieck', MX, 20); }
  fuente(doc, 'bold', 10.5, AZUL); doc.text(pdfTxt(b.folio || 'SIN FOLIO'), PW - MX, 14, { align:'right' });
  fuente(doc, 'normal', 7.5, GRIS); doc.text('Requisición de personal', PW - MX, 18.5, { align:'right' });
  return primera ? 33 : TOPE_PAG;
}
function pdfPies(doc, b){
  const n = doc.getNumberOfPages();
  for(let i = 1; i <= n; i++){
    doc.setPage(i);
    fuente(doc, 'normal', 8, GRIS); doc.text(i + ' / ' + n, PW - MX, 23, { align:'right' });
    doc.setDrawColor(0, 0, 0); doc.setLineWidth(0.35); doc.line(22, PIE_Y, PW - 22, PIE_Y);
    fuente(doc, 'normal', 8.5, [0, 0, 0]);
    doc.text(pdfTxt(PIE_1), PW / 2, PIE_Y + 4.2, { align:'center' });
    doc.text(pdfTxt(PIE_2), PW / 2, PIE_Y + 8, { align:'center' });
    fuente(doc, 'normal', 8.5, [5, 99, 193]);
    const ww = doc.getTextWidth(PIE_WEB);
    doc.textWithLink(PIE_WEB, (PW - ww) / 2, PIE_Y + 11.8, { url:PIE_WEB });
    doc.setDrawColor(5, 99, 193); doc.setLineWidth(0.2); doc.line((PW - ww) / 2, PIE_Y + 12.4, (PW + ww) / 2, PIE_Y + 12.4);
  }
}
function pdfNueva(doc, b){ doc.addPage(); return pdfMembrete(doc, b, false); }
function pdfEspacio(doc, b, y, alto){ return (y + alto > LIMITE) ? pdfNueva(doc, b) : y; }

function pdfTituloSec(doc, b, y, txt){
  y = pdfEspacio(doc, b, y, 24);
  doc.setFillColor(...SUAVE); doc.roundedRect(MX - 2, y - 4.6, ANCHO + 4, 7.6, 1.6, 1.6, 'F');
  fuente(doc, 'bold', 9.5, AZUL); doc.text(pdfTxt(txt.toUpperCase()), MX + 1, y + 0.6);
  return y + 9;
}
function pdfBandaOscura(doc, b, y, txt){
  y = pdfEspacio(doc, b, y, 18);
  doc.setFillColor(...TINTA); doc.rect(MX, y, ANCHO, 5.2, 'F');
  fuente(doc, 'bold', 7.2, [255,255,255]); doc.text(pdfTxt(txt.toUpperCase()), PW / 2, y + 3.6, { align:'center' });
  return y + 5.2;
}

/* Cuadro de celdas (sección I). Cada fila toma la altura de su celda más larga,
   así el texto nunca se encima, sean 2 palabras o 2 párrafos. Si una fila no cabe
   ni en una hoja completa, continúa en la siguiente. */
function pdfGrid(doc, b, y, items, cols){
  const cw = ANCHO / cols, PADX = 1.6, LH_L = 2.7, LH_V = 3.9;
  const filas = []; let fila = [], usado = 0;
  const cerrar = () => {
    if(!fila.length) return;
    if(usado < cols) fila[fila.length - 1].span += cols - usado;
    filas.push({ celdas:fila }); fila = []; usado = 0;
  };
  items.forEach(it => {
    if(it.band){ cerrar(); filas.push({ band:it.l }); return; }
    const sp = Math.min(it.span || 1, cols);
    if(usado + sp > cols) cerrar();
    fila.push({ l:it.l, v:it.v, span:sp }); usado += sp;
  });
  cerrar();

  const dibujar = (prep, y0, alto, desde, hasta) => {
    let x = MX;
    prep.forEach((p, i) => {
      const w = p.span * cw;
      doc.setDrawColor(...LINEA); doc.setLineWidth(0.25); doc.rect(x, y0, w, alto);
      fuente(doc, 'bold', 6.6, GRIS); doc.text(p.ll, x + PADX, y0 + 3.3);
      fuente(doc, 'normal', 9, p.vacio ? [185,185,195] : TINTA);
      const vl = p.vl.slice(desde[i], hasta[i]);
      vl.forEach((l, j) => doc.text(l, x + PADX, y0 + 3.3 + p.ll.length * LH_L + 2.5 + j * LH_V));
      x += w;
    });
  };

  filas.forEach(f => {
    if(f.band){ y = pdfBandaOscura(doc, b, y, f.band); return; }
    const prep = f.celdas.map(c => {
      const w = c.span * cw - 2 * PADX;
      fuente(doc, 'bold', 6.6); const ll = renglones(doc, pdfTxt(c.l.toUpperCase()), w);
      fuente(doc, 'normal', 9); const vl = renglones(doc, pdfTxt(c.v || '-'), w);
      return { ll, vl, span:c.span, vacio:!c.v };
    });
    const cab = Math.max(...prep.map(p => 2.8 + p.ll.length * LH_L + 1.4));
    let desde = prep.map(() => 0);
    const total = prep.map(p => p.vl.length);
    const altoCompleto = Math.max(11, cab + Math.max(...total) * LH_V + 1.6);
    if(y + altoCompleto > LIMITE && altoCompleto <= LIMITE - TOPE_PAG) y = pdfNueva(doc, b);
    /* se dibuja por tramos: normalmente es uno solo */
    while(true){
      const caben = Math.max(1, Math.floor((LIMITE - y - cab - 1.6) / LH_V));
      const hasta = total.map((n, i) => Math.min(n, desde[i] + caben));
      const lineas = Math.max(...hasta.map((h, i) => h - desde[i]));
      const alto = Math.max(11, cab + lineas * LH_V + 1.6);
      dibujar(prep, y, alto, desde, hasta);
      y += alto; desde = hasta;
      if(desde.every((d0, i) => d0 >= total[i])) break;
      y = pdfNueva(doc, b);
    }
  });
  return y + 6;
}

/* Casillas tipo ☐ Sí ☐ No */
function pdfCasillas(doc, b, y, x0, ops, sel){
  let x = x0;
  y = pdfEspacio(doc, b, y - 3, 6) + 3;
  ops.forEach(o => {
    const t = pdfTxt(o); fuente(doc, marcado(o, sel) ? 'bold' : 'normal', 9.5);
    const w = 5 + doc.getTextWidth(t) + 7;
    if(x + w > PW - MX){ x = x0; y += 5.5; y = pdfEspacio(doc, b, y - 3, 6) + 3; fuente(doc, marcado(o, sel) ? 'bold' : 'normal', 9.5); }
    doc.setDrawColor(...TINTA); doc.setLineWidth(0.3); doc.rect(x, y - 3, 3.3, 3.3);
    if(marcado(o, sel)){ doc.setFillColor(...AZUL); doc.rect(x + 0.6, y - 2.4, 2.1, 2.1, 'F'); }
    doc.setTextColor(...(marcado(o, sel) ? AZUL : TINTA));
    doc.text(t, x + 4.8, y);
    x += w;
  });
  return y + 6;
}
/* Respuesta escrita sobre renglones: tantos renglones como necesite el texto */
function pdfRenglones(doc, b, y, x0, texto, minLineas){
  fuente(doc, 'normal', 9.5);
  const lines = texto ? renglones(doc, pdfTxt(texto), PW - MX - x0 - 2) : [];
  const n = Math.max(lines.length, minLineas || 1);
  for(let i = 0; i < n; i++){
    y = pdfEspacio(doc, b, y, 7);
    fuente(doc, 'normal', 9.5, TINTA);
    if(lines[i]) doc.text(lines[i], x0 + 1, y + 4);
    doc.setDrawColor(...LINEA); doc.setLineWidth(0.25); doc.line(x0, y + 5.4, PW - MX, y + 5.4);
    y += 6.6;
  }
  return y + 2;
}
function pdfPregunta(doc, b, y, n, label, c, d){
  const xT = MX + 7;
  fuente(doc, 'normal', 10);
  const ql = renglones(doc, pdfTxt(label), PW - MX - xT);
  y = pdfEspacio(doc, b, y, ql.length * 4.4 + 12);
  fuente(doc, 'normal', 10, TINTA);
  if(n) doc.text(n + '.', MX + 1.5, y);
  ql.forEach((l, j) => doc.text(l, xT, y + j * 4.4));
  y += ql.length * 4.4 + 1.2;
  const v = d[c.id];
  if(c.t === 'seg') return pdfCasillas(doc, b, y + 1, xT, c.op, v) + 1.5;
  if(c.t === 'lista'){
    const arr = (Array.isArray(v) ? v : []).filter(x => x && String(x).trim());
    const items = arr.length ? arr : ['', '', ''];
    items.forEach(it => {
      fuente(doc, 'normal', 9.5);
      const ls = it ? renglones(doc, pdfTxt(it), PW - MX - xT - 6) : [''];
      ls.forEach((l, j) => {
        y = pdfEspacio(doc, b, y, 6);
        fuente(doc, 'normal', 9.5, TINTA);
        if(j === 0){ doc.setFillColor(...TINTA); doc.circle(xT + 1.2, y + 2.6, 0.7, 'F'); }
        doc.text(l, xT + 4.5, y + 3.6);
        if(!it){ doc.setDrawColor(...LINEA); doc.line(xT + 4.5, y + 4.4, PW - MX, y + 4.4); }
        y += 4.4;
      });
      y += 1.6;
    });
    return y + 2;
  }
  return pdfRenglones(doc, b, y, xT, valorTexto(c, d), c.t === 'area' ? 2 : 1) + 2.5;
}


/* ================== PDF de la requisición (hoja carta, como el formato en Word) ================== */
function marcado(o, sel){ return Array.isArray(sel) ? sel.indexOf(o) >= 0 : o === sel; }
function celdas(d, ids){
  return ids.map(id => CAMPO[id]).filter(c => c && visible(c, d))
    .map(c => ({ l:etiquetaPDF(c, d), v:valorTexto(c, d), span:c.ps || 1 }));
}
/* Renglón con etiqueta a la izquierda y casillas ( ) a la derecha */
function pdfOpciones(doc, b, y, etiq, ops, sel){
  y = pdfEspacio(doc, b, y, 9);
  fuente(doc, 'bold', 9, TINTA);
  const el = renglones(doc, pdfTxt(etiq), 44);
  doc.text(el, MX + 1, y);
  const y2 = pdfCasillas(doc, b, y, MX + 48, ops, sel);
  return Math.max(y2, y + el.length * 4 + 2);
}
/* Recuadros de firma: firma dibujada (si la hay) sobre la línea, nombre y cargo abajo */
function pdfFirmas(doc, b, y, firmas){
  const H = 40;
  y = pdfEspacio(doc, b, y, H + 4);
  const n = firmas.length, gap = 6, w = (ANCHO - gap * (n - 1)) / n;
  firmas.forEach((f, i) => {
    const x = MX + i * (w + gap), base = y + 24;
    doc.setDrawColor(...LINEA); doc.setLineWidth(0.3); doc.roundedRect(x, y, w, H, 1.5, 1.5);
    if(f.img){
      const ih = 20, iw = Math.min(w - 10, ih * (f.ratio || 3));
      try{ doc.addImage(f.img, 'PNG', x + (w - iw) / 2, base - ih - 0.5, iw, ih, undefined, 'FAST'); }catch(e){}
    }
    doc.setDrawColor(...TINTA); doc.setLineWidth(0.3); doc.line(x + 6, base, x + w - 6, base);
    fuente(doc, 'bold', 8.5, TINTA);
    doc.text(renglones(doc, pdfTxt(f.nombre || ' '), w - 6)[0] || '', x + w / 2, base + 4.5, { align:'center' });
    fuente(doc, 'bold', 7, GRIS);
    doc.text(pdfTxt(f.rol.toUpperCase()), x + w / 2, base + 8.5, { align:'center' });
    if(f.rechazo){ fuente(doc, 'bold', 7, [166,27,27]); doc.text(pdfTxt(f.rechazo), x + w / 2, base + 12.3, { align:'center' }); }
    else if(f.cuando){ fuente(doc, 'italic', 6.5, GRIS); doc.text(pdfTxt('Firmado electrónicamente el ' + String(f.cuando).replace(/ \(zona.*\)$/, '')), x + w / 2, base + 12.3, { align:'center' }); }
    else if(f.pendiente){ fuente(doc, 'italic', 6.5, GRIS); doc.text(pdfTxt('Pendiente de firma por correo'), x + w / 2, base + 12.3, { align:'center' }); }
  });
  return y + H + 4;
}
function firmaDe(b, quien){ const f = (b.firmas || {})[quien]; return f && f.img ? f : null; }

function generarPDF(b){
  if(!window.jspdf || !window.jspdf.jsPDF) throw new Error('No cargó el generador de PDF. Revisa tu conexión y recarga la página.');
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'mm', format:'letter', orientation:'portrait' });
  const d = b.d || {};
  let y = pdfMembrete(doc, b, true);

  fuente(doc, 'bold', 15, TINTA);
  doc.text('REQUISICIÓN DE PERSONAL', PW / 2, y, { align:'center' });
  y += 8;
  fuente(doc, 'bold', 9.5, TINTA);
  const fTxt = pdfTxt(fechaFormato(b.fecha || hoyISO()));
  fuente(doc, 'normal', 9.5); const wF = doc.getTextWidth(fTxt);
  doc.text(fTxt, PW - MX, y, { align:'right' });
  fuente(doc, 'bold', 9.5); doc.text('Fecha de solicitud: ', PW - MX - wF, y, { align:'right' });
  y += 8;

  y = pdfTituloSec(doc, b, y, 'Datos del solicitante');
  y = pdfGrid(doc, b, y, celdas(d, ['solNombre','solPuesto','solArea','solCorreo','director']), 4);

  y = pdfTituloSec(doc, b, y, 'Estatus del puesto');
  y = pdfCasillas(doc, b, y, MX + 2, CAMPO.estatusPuesto.op, d.estatusPuesto) + 4;

  y = pdfTituloSec(doc, b, y, 'Información de la requisición');
  y = pdfGrid(doc, b, y, celdas(d, ['nombrePuesto','numVacantes','escolaridad','carrera','titulo','cedula','sexo','sexoMotivo',
    'experiencia','competencias','certificaciones','reportaA','sueldo','fechaIngreso','centro']), 4);

  y = pdfTituloSec(doc, b, y, 'Condiciones del puesto');
  y = pdfOpciones(doc, b, y, 'Tipo de contratación', CAMPO.contratacion.op, d.contratacion);
  y = pdfOpciones(doc, b, y, 'Horario laboral', CAMPO.dias.op, d.dias);
  y = pdfOpciones(doc, b, y, 'Tipo de jornada laboral', CAMPO.jornada.op, d.jornada);
  y = pdfOpciones(doc, b, y, 'Disponibilidad', CAMPO.disponibilidad.op, d.disponibilidad) + 4;

  y = pdfTituloSec(doc, b, y, 'Motivo de la requisición');
  y = pdfCasillas(doc, b, y, MX + 2, CAMPO.motivo.op, d.motivo) + 2;
  const det = celdas(d, ['motivoDef','motivoTemp','reemplazaA','motivoOtro']);
  y = det.length ? pdfGrid(doc, b, y, det, 4) : y + 4;

  y = pdfTituloSec(doc, b, y, 'En caso de ser proyecto');
  if(esProyecto(d)){
    y = pdfGrid(doc, b, y, celdas(d, ['proyNombre','proyCliente','proyInicio','proyFin','proyUbicacion','proyResponsable','viaticos','proyComentarios']), 4);
    y = pdfTituloSec(doc, b, y, 'Otras consideraciones para el puesto');
    y = pdfRenglones(doc, b, y, MX + 2, valorTexto(CAMPO.otras, d), 2) + 4;
  }
  else { fuente(doc, 'italic', 9.5, GRIS); doc.text('No aplica.', MX + 2, y); y += 9; }

  y = pdfTituloSec(doc, b, y, 'Activos y herramientas a asignar');
  y = pdfCasillas(doc, b, y, MX + 2, CAMPO.activos.op, d.activos) + 1;
  if(visible(CAMPO.activosOtro, d)) y = pdfGrid(doc, b, y, celdas(d, ['activosOtro']), 4); else y += 4;

  y = pdfEspacio(doc, b, y, 112);          /* firmas siempre juntas, sin título huérfano */
  y = pdfTituloSec(doc, b, y, 'Firmas');
  const fs = firmaDe(b, 'sol');
  y = pdfFirmas(doc, b, y, [Object.assign({ rol:'Nombre y firma del solicitante', nombre:d.solNombre }, fs || {})]);
  fuente(doc, 'bold', 9.5, AZUL); y = pdfEspacio(doc, b, y, 50);
  doc.text('AUTORIZADO POR', PW / 2, y + 2, { align:'center' }); y += 6;
  y = pdfFirmas(doc, b, y, [cajaFirma(b, 'dir', 'Director del área', d.director), cajaFirma(b, 'rh', 'Autoriza', AUTORIZA_RH)]);

  /* Uso exclusivo de RH (en blanco) */
  y = pdfEspacio(doc, b, y + 8, 75);
  y = pdfBandaOscura(doc, b, y, 'Uso exclusivo de Recursos Humanos') + 9;
  y = pdfGrid(doc, b, y, [
    { l:'Fecha de recepción', v:'', span:2 }, { l:'Medio solicitado', v:'', span:2 },
    { l:'Reclutador asignado', v:'', span:2 }, { l:'Fecha de cierre', v:'', span:2 },
    { l:'Candidato contratado', v:'', span:2 }, { l:'Fecha de ingreso', v:'', span:2 },
    { l:'Sueldo mensual neto autorizado', v:'', span:4 }
  ], 4);
  y = pdfOpciones(doc, b, y, 'Tipo de solicitud', ['Ordinaria','Extraordinaria','Emergente'], null);

  pdfEvidencias(doc, b);
  pdfPies(doc, b);
  return doc;
}
/* Firma de un autorizador según el flujo de firmas por correo */
function firmante(b, tipo){ return (b.flujo || []).find(f => (f.tipos || []).indexOf(tipo) >= 0) || null; }
function cajaFirma(b, tipo, rol, nombre){
  const f = firmante(b, tipo);
  const o = { rol, nombre:f ? f.nombre : nombre };
  if(f && f.estado === 'Autorizó' && f.img) Object.assign(o, { img:f.img, ratio:3, cuando:f.cuando });
  else if(f && f.estado === 'Rechazó') o.rechazo = 'RECHAZÓ el ' + String(f.cuando).replace(/ \(zona.*\)$/, '');
  else o.pendiente = true;
  return o;
}
/* Hoja de evidencias: quién firmó, con qué correo, en qué orden y cuándo */
function pdfEvidencias(doc, b){
  const fl = b.flujo || [];
  if(!fl.some(f => f.estado !== 'Pendiente')) return;
  let y = pdfNueva(doc, b);
  fuente(doc, 'bold', 13, TINTA);
  doc.text(pdfTxt('HOJA DE EVIDENCIAS DE FIRMA ELECTRÓNICA'), PW / 2, y, { align:'center' }); y += 8;
  const estado = b.rechazada ? 'Rechazada' : (fl.every(f => f.estado === 'Autorizó') ? 'Autorizada (todas las firmas completas)' : 'En proceso de firma');
  y = pdfGrid(doc, b, y, [
    { l:'Folio', v:b.folio, span:1 }, { l:'Estado del documento', v:estado, span:3 },
    { l:'Recibida por el sistema', v:b.recibida || '', span:2 }, { l:'Código de verificación', v:b.codigo || '', span:2 },
    { l:'Identificador interno', v:b.id, span:4 }
  ], 4);
  y = pdfTituloSec(doc, b, y, 'Registro de firmas');
  const filas = [{ n:'—', rol:'Solicitante', nombre:(firmaDe(b, 'sol') || {}).nombre || b.d.solNombre, correo:b.d.solCorreo,
    res:'Firmó en el formulario web', cuando:(firmaDe(b, 'sol') || {}).cuando || b.recibida, medio:'Formulario web de requisición (correo declarado)' }]
    .concat(fl.map(f => ({ n:String(f.orden), rol:f.rol, nombre:f.nombre, correo:f.correo, res:f.estado === 'Pendiente' ? 'Pendiente' : f.estado,
      cuando:f.cuando || '', medio:f.estado === 'Pendiente' ? 'Correo enviado; aún no firma' : (f.medio || 'Liga única enviada por correo'), motivo:f.motivo })));
  filas.forEach(r => {
    const items = [
      { l:'Orden', v:r.n, span:1 }, { l:'Rol', v:r.rol, span:1 }, { l:'Nombre', v:r.nombre, span:2 },
      { l:'Correo electrónico', v:r.correo || '', span:2 }, { l:'Resultado', v:r.res, span:1 }, { l:'Fecha y hora', v:String(r.cuando || '').replace(/ \(zona.*\)$/, ''), span:1 }
    ];
    if(r.motivo) items.push({ l:'Motivo del rechazo', v:r.motivo, span:4 });
    y = pdfGrid(doc, b, y, items, 4);
  });
  y = pdfEspacio(doc, b, y + 2, 22);
  fuente(doc, 'italic', 8, GRIS);
  renglones(doc, pdfTxt('El solicitante firmó en el formulario web de requisición con el correo que declaró. Cada autorizador recibió en su correo electrónico ' +
    'una liga personal y única para revisar y firmar este documento, en el orden indicado. Las fechas y horas las registra el servidor (zona centro de México). ' +
    'Al completar cada firma se envió una confirmación con el PDF al correo del firmante y un aviso a Recursos Humanos (recursoshumanos@mdreieck.com.mx).'), ANCHO).forEach(l => { doc.text(l, MX, y); y += 4; });
}
function nombrePDF(b){ return b.folio + ' - ' + slugNombre(b.d.nombrePuesto) + ' - ' + slugNombre(b.d.solArea) + '.pdf'; }

/* ================== ENVIO ================== */
async function enviarRequisicion(b, prog){
  if(!b.folio){
    prog('Asignando folio…', 'Un momento, por favor.');
    b.folio = await pedirFolio();
    guardarBorrador(b);
  }
  if(!b.fecha){ b.fecha = hoyISO(); guardarBorrador(b); }
  prog('Generando el PDF…', 'Armando la requisición.');
  const doc = generarPDF(b);
  const s = doc.output('datauristring');
  prog('Enviando a Recursos Humanos…', 'No cierres esta página.');
  await postServidor({
    accion:'requisicion', id:b.id, folio:b.folio, hp:b.hp || '', fecha:b.fecha,
    puesto:b.d.nombrePuesto || '', area:b.d.solArea || '', solicitante:b.d.solNombre || '',
    correo:b.d.solCorreo || '', director:b.d.director || '', vacantes:b.d.numVacantes || '', fechaIngreso:b.d.fechaIngreso || '',
    columnas:columnasSheet(b).concat([
      ['Firma del solicitante', firmaDe(b, 'sol') ? 'Firmó: ' + b.firmas.sol.nombre + ' (' + b.firmas.sol.cuando + ')' : 'Sin firma']
    ]),
    datos:{ id:b.id, folio:b.folio, fecha:b.fecha, d:b.d, firmas:{ sol:firmaDe(b, 'sol') } },
    pdf:{ name:nombrePDF(b), data:s.slice(s.indexOf('base64,') + 7) }
  });
  return doc;
}
